sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var gate = new x_ssa_day2_ops.EntraHelpdeskGate();
  var verdict = gate.preflight({
    requester_id: 'day2-requester-sysid',
    approver_id: 'day2-approver-sysid',   // properly distinct - SoD is satisfied
    privileged: true                      // ...but no expiry supplied
  });
  if (verdict.ok) { stepResult.setFailed('standing privilege allowed: privileged grant with no expiry passed (AC-6)'); return; }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var gate = new x_ssa_day2_ops.EntraHelpdeskGate();
  var verdict = gate.preflight({
    requester_id: 'day2-requester-sysid',
    approver_id: 'day2-approver-sysid',
    privileged: true,
    expiry: '2026-12-31 17:00:00'
  });
  verdict.ok ? stepResult.setSuccess()
             : stepResult.setFailed('a time-bound privileged grant should pass: ' + verdict.reason);
})(outputs, steps, stepResult);
